mapper.select:




    and del_flag = '0'

     and reservation_id = #{reservationId}

     and reservation_no like concat('%', #{reservationNo}, '%')

     and reservation_type = #{reservationType}

     and applicant_id = #{applicantId}

     and applicant_name like concat('%', #{applicantName}, '%')

     and applicant_role like concat('%', #{applicantRole}, '%')

     and applicant_phone like concat('%', #{applicantPhone}, '%')

     and org_id = #{orgId}

     and org_name like concat('%', #{orgName}, '%')

     and title like concat('%', #{title}, '%')

     and purpose like concat('%', #{purpose}, '%')

     and people_count = #{peopleCount}

     and detail_remark like concat('%', #{detailRemark}, '%')

     and status = #{status}
     and audit_type = #{auditType}

        and status in ('1', '3')
        and audit_type = '0'
        and exists (
            select 1
            from space_reservation_item sri
            where sri.reservation_id = space_reservation.reservation_id
              and sri.item_status in ('1', '4')
        )



        and status = '1'
        and audit_type = '1'
        and exists (
            select 1
            from space_reservation_item sri
            where sri.reservation_id = space_reservation.reservation_id
              and sri.item_status = '1'
        )


     and submit_time = #{submitTime}
     and auditor_id = #{auditorId}

     and auditor_name like concat('%', #{auditorName}, '%')

     and audit_time = #{auditTime}

     and reject_reason like concat('%', #{rejectReason}, '%')

     and version = #{version}



order by reservation_id desc
